cat > $P/lits0.json <<'MORPH_LITS_EOF'
["TestPMToolsExample1", "TestPMToolsExample2", "TestPMToolsExample3", "TestPMToolsExample4", "TestPMToolsExample5", "TestPMToolsExample6", "TestPMToolsExample7", "NewInMemoryTransports", "answer", "continue", "interrupt", "order", "pending", "plan_load", "restart", "status", "stop_check", "usage", "projects_list", "project_create", "../tests/fixtures/plan/queue-3.json", "smoke checked green. Resume with P12b", "no_question: no pending question", "internal: disk full", "beta", "one", "7b31dfe", "1.92", "2026-10-08T15:00:00Z", "1791469200", "1791853200", "5.2609", "2026-10-08T13:09:03Z", "https://github.com/o/demo", "https://github.com/o/alpha", "2026-10-07T09:00:00Z", "StructuredContent"]
MORPH_LITS_EOF
echo '== guard mcpserver/pm_examples_test.go'; node $P/guard.mjs tests mcpserver/pm_examples_test.go 7 13 $P/lits0.json
echo '== own'; go test -count=1 -overlay $P/overlay.json ./mcpserver > $P/gt.log 2>&1 || { if grep -q '^--- FAIL' $P/gt.log; then awk '/^--- FAIL/{p=1} p' $P/gt.log | grep -vE '^(ok[[:space:]]|PASS$|FAIL$)' | head -200; else tail -60 $P/gt.log; fi; node $P/firstdiff.mjs $P/gt.log; exit 1; }
[ "$E" = 0 ] || { echo "== vet or gofmt failed (see above); every step between it and here passed"; exit 1; }
echo '== full'; go test -count=1 -overlay $P/full.json ./... > $P/gt.log 2>&1 || { if grep -q '^--- FAIL' $P/gt.log; then awk '/^--- FAIL/{p=1} p' $P/gt.log | grep -vE '^(ok[[:space:]]|PASS$|FAIL$)' | head -200; else tail -60 $P/gt.log; fi; node $P/firstdiff.mjs $P/gt.log; exit 1; }
echo '== frozen'; git diff --quiet HEAD -- contour.yaml morph-map.json docs decks tests/fixtures go.mod go.sum internal vendor stream runner queue session eventlog telegram claude github bootstrap registry gitrules control supervisor api || { echo "changed outside the targets: $(git diff --name-only HEAD -- contour.yaml morph-map.json docs decks tests/fixtures go.mod go.sum internal vendor stream runner queue session eventlog telegram claude github bootstrap registry gitrules control supervisor api | tr "\n" " ")"; exit 1; }
X=$(git ls-files --others --exclude-standard | grep -vxF -e mcpserver/pm_examples_test.go || true); [ -z "$X" ] || { echo "files left in the tree: $X"; exit 1; }
) > $L 2>&1; rc=$?; cat $L; exit $rc
